//! Independent memory-only PakViewer .NET10 reference results, 2026-09-15.
//! Expected pixels below were not generated by the Rust decoder under test.
use super::super::{combat_animation::NativeAudioMode, inventory_icons::SharedInventoryIcons};
use super::*;

#[test]
#[ignore = "LITO_SHARED_RESOURCE_ROOT; shared 28 SPR frames, four TBTs, two WAVs; no window or audio device"]
